SELECT a.account_type, YEAR(a.opened_date) AS opened_year, ROUND((100 * SUM(CASE WHEN t.merchant = 'Amazon' THEN 1 ELSE 0 END)) / COUNT(*), 1) AS pct_amazon, SUM(CASE WHEN t.txn_type = 'DEBIT' THEN 1 ELSE 0 END) AS debit_count FROM transactions t INNER JOIN accounts a ON t.account_id = a.id WHERE a.status IS NULL GROUP BY a.account_type, YEAR(a.opened_date) HAVING SUM(CASE WHEN t.txn_type = 'DEBIT' THEN 1 ELSE 0 END) > 58;
